public final class GreeterTest {
    public static void main(String[] args) {
        String got = Greeter.greet();
        String want = "Hello, " + Config.NAME + "!";
        if (!got.equals(want)) {
            throw new AssertionError("Greeter.greet() = \"" + got + "\", want \"" + want
                    + "\" (the CURRENT Config.NAME, not a stale value)");
        }
        System.out.println("all tests passed");
    }
}

